import {
  createSystem,
  WorldTransform,
} from "/worker-modules/packages/app/dist/systems.js";
import {
  createMeshHandle,
  createMaterialHandle,
  serializeEntityRef,
} from "/worker-modules/packages/simulation/dist/index.js";
import {
  createTriangleListMeshAsset,
  createStandardMaterialAsset,
} from "/worker-modules/packages/render/dist/index.js";
import { STATES, INITIAL_EDIT, SHARED, LIGHT } from "/harness/contract.mjs";
import { CAMERAS, PALETTE, constructScene, linearColor } from "./scene.mjs";
import {
  nativeMeshEvidence,
  compareNativeToSource,
  jsonValue,
} from "./native-evidence.mjs";
export const LIVE_CHANNEL = "crane.live.apply";
export let sceneOwner = null;
export const meshKeyFor = (part) =>
  part.instance === null || SHARED ? part.partName : part.name;
export function createPartAsset(part, label = meshKeyFor(part)) {
  return createTriangleListMeshAsset({
    label,
    positions: part.positions,
    indices: part.indices,
  });
}
export class CraneCourtyard extends createSystem({ priority: 0 }) {
  init() {
    if (sceneOwner) throw Error("Second persistent scene");
    sceneOwner = this;
    this.originalWorld = this.world;
    this.world.globals.craneLiveSceneId = crypto.randomUUID();
    this.scene = constructScene(INITIAL_EDIT);
    this.revision = 0;
    this.stateId = null;
    this.entries = new Map();
    this.fixtureAssets = new Map();
    this.fixtureMaterials = new Map();
    this.publications = [];
    this.counters = {
      initialMeshAssets: 0,
      meshAssetReplacements: 0,
      publishedVertexArrayReplacements: 0,
      publishedIndexArrayReplacements: 0,
      entityCreateCalls: 0,
      entityDestroyCalls: 0,
    };
    const create = this.world.createEntity;
    this.world.createEntity = (...args) => {
      const entity = create.apply(this.world, args);
      this.counters.entityCreateCalls++;
      const destroy = entity.destroy;
      entity.destroy = (...xs) => {
        this.counters.entityDestroyCalls++;
        return destroy.apply(entity, xs);
      };
      return entity;
    };
    for (const part of this.scene.parts) {
      const key = meshKeyFor(part),
        materialKey = part.partName;
      if (!this.fixtureAssets.has(key)) {
        const handle = createMeshHandle(key + ".mesh"),
          asset = createPartAsset(part, key);
        this.assetsRegistry.register(handle);
        this.assetsRegistry.markReady(handle, asset);
        this.fixtureAssets.set(key, {
          handle,
          asset,
          assetSerial: ++this.counters.initialMeshAssets,
          publishes: 0,
        });
      }
      if (!this.fixtureMaterials.has(materialKey)) {
        const [hex, roughness, metallic] = PALETTE[part.material],
          handle = createMaterialHandle(materialKey + ".material");
        this.assetsRegistry.register(handle);
        this.assetsRegistry.markReady(
          handle,
          createStandardMaterialAsset({
            baseColorFactor: [...linearColor(hex), 1],
            roughnessFactor: roughness,
            metallicFactor: metallic,
          }),
        );
        this.fixtureMaterials.set(materialKey, handle);
      }
      const entry = this.fixtureAssets.get(key),
        material = this.fixtureMaterials.get(materialKey);
      const entity = this.spawn.mesh({
        key: part.name,
        name: part.name,
        mesh: entry.handle,
        material,
        transform: { translation: part.translation },
        castShadow: true,
        receiveShadow: true,
      });
      this.entries.set(part.name, {
        entity,
        originalEntity: entity,
        entry,
        material,
      });
    }
    this.spawn.camera({
      key: "camera.main",
      transform: { translation: CAMERAS["front-quarter"], lookAt: [0, 1.4, 0] },
      camera: {
        projection: "orthographic",
        orthographicHeight: 10.5,
        aspect: 1,
        autoAspect: false,
        near: 0.1,
        far: 80,
        clearColor: [0.115, 0.17, 0.209, 1],
        frustumCulling: true,
      },
    });
    this.spawn.light({
      key: "light.key",
      kind: LIGHT.kind,
      color: LIGHT.color,
      intensity: LIGHT.intensity,
      transform: { translation: LIGHT.position, lookAt: LIGHT.target },
      shadow: LIGHT.shadow,
    });
    this.initialEntityCount = this.world.entityVersionTrackingSize();
  }
  update() {
    const requests = this.commands.drain(LIVE_CHANNEL);
    if (requests.length > 1) throw Error("Concurrent edits forbidden");
    if (!requests.length) return;
    const request = requests[0],
      state = STATES[request.index];
    if (
      !state ||
      request.id !== state.id ||
      request.revision !== state.index + 1 ||
      request.revision !== this.revision + 1
    )
      throw Error("revision/state sequence mismatch");
    const next = constructScene(state.edit);
    this.lastChangedMeshes = [];
    if (this.scene.edit !== next.edit) {
      const replaced = new Set();
      for (const part of next.parts.filter((p) => p.instance !== null)) {
        const key = meshKeyFor(part);
        if (replaced.has(key)) continue;
        replaced.add(key);
        const entry = this.fixtureAssets.get(key),
          asset = createPartAsset(part, key),
          result = this.meshes.publish(entry.handle, asset);
        if (
          result.handle.id !== entry.handle.id ||
          this.meshes.get(entry.handle) !== asset
        )
          throw Error("Publication identity failure");
        this.counters.meshAssetReplacements++;
        this.counters.publishedVertexArrayReplacements +=
          asset.vertexStreams.filter(
            (s, i) => s.data !== entry.asset.vertexStreams[i]?.data,
          ).length;
        entry.asset = asset;
        entry.assetSerial =
          this.counters.initialMeshAssets + this.counters.meshAssetReplacements;
        entry.publishes++;
        const record = {
          name: key,
          meshId: entry.handle.id,
          version: result.version,
          revision: request.revision,
        };
        this.lastChangedMeshes.push(record);
        this.publications.push(record);
      }
    }
    this.scene = next;
    this.revision = request.revision;
    this.stateId = request.id;
  }
  evidenceAtNativePublication(frame, snapshot) {
    if (this.world !== this.originalWorld) throw Error("World replaced");
    const nativeMeshes = [];
    for (const part of this.scene.parts) {
      const { entity, originalEntity, entry, material } = this.entries.get(
          part.name,
        ),
        registry = this.assetsRegistry.get(entry.handle);
      if (
        entity !== originalEntity ||
        !entity.active ||
        registry.asset !== entry.asset
      )
        throw Error("Native identity changed");
      const matrix = ["col0", "col1", "col2", "col3"].flatMap((k) =>
        Array.from(entity.getVectorView(WorldTransform, k)),
      );
      nativeMeshes.push(
        nativeMeshEvidence(part.name, entry.asset, matrix, {
          partName: part.partName,
          instance: part.instance,
          assetLabel: entry.asset.label,
          entityId: serializeEntityRef(entity),
          meshId: entry.handle.id,
          materialId: material.id,
          assetKey: registry.key,
          assetVersion: registry.version,
          assetSerial: entry.assetSerial,
          publishes: entry.publishes,
        }),
      );
    }
    const nativeChecks = compareNativeToSource(this.scene, nativeMeshes);
    nativeChecks.checks.push({
      name: "real-entity-count-stable",
      ok: this.initialEntityCount === this.world.entityVersionTrackingSize(),
    });
    nativeChecks.ok = nativeChecks.checks.every((c) => c.ok);
    return {
      stateId: this.stateId,
      revision: this.revision,
      snapshotFrame: frame,
      snapshotFrameField: snapshot.frame,
      shared: SHARED,
      parameters: this.scene.parameters,
      identity: {
        sceneId: this.world.globals.craneLiveSceneId,
        entityCount: this.world.entityVersionTrackingSize(),
        meshCount: nativeMeshes.length,
        meshes: nativeMeshes.map(({ name, entityId, meshId, materialId }) => ({
          name,
          entityId,
          meshId,
          materialId,
        })),
      },
      sourceGeometry: jsonValue(this.scene),
      nativeGeometry: { meshes: nativeMeshes },
      nativeChecks,
      resources: {
        ...this.counters,
        currentMeshAssets: this.fixtureAssets.size,
        changedMeshes: this.lastChangedMeshes ?? [],
        publications: [...this.publications],
        assetVersions: nativeMeshes.map(
          ({ name, meshId, assetVersion, publishes }) => ({
            name,
            meshId,
            assetVersion,
            publishes,
          }),
        ),
      },
    };
  }
}

sourceFiles.worker.mjs:
import { startGeneratedSimulationWorker } from "/worker-modules/packages/app/dist/worker.js";
import { SIMULATION_WORKER_PROTOCOL } from "/worker-modules/packages/runtime/dist/index.js";
import { CONFIG } from "./scene.mjs";
import { CraneCourtyard, sceneOwner } from "./scene-system.mjs";

// Observe the exact native publication boundary. The engine still owns stepping,
// extraction, asset serialization, transfer lists and the persistent ECS world.
let connected = false;
globalThis.addEventListener("message", (event) => {
  if (event.data?.type !== SIMULATION_WORKER_PROTOCOL.connect) return;
  if (connected) throw Error("Second native worker connection rejected");
  connected = true;
  const port = event.data.port;
  const observedPort = {
    addEventListener: (...args) => port.addEventListener(...args),
    removeEventListener: (...args) => port.removeEventListener(...args),
    start: () => port.start(),
    close: () => port.close(),
    postMessage(message, transfer) {
      let outgoing = message;
      if (message.type === SIMULATION_WORKER_PROTOCOL.snapshot)
        globalThis.postMessage({
          type: "crane-live-publication-trace",
          frame: message.frame,
          snapshotFrame: message.snapshot.frame,
          revision: sceneOwner?.revision ?? null,
          stateId: sceneOwner?.stateId ?? null,
          full: message.workerSummary?.summaryCadence?.full ?? null,
        });
      if (
        sceneOwner?.revision > 0 &&
        message.type === SIMULATION_WORKER_PROTOCOL.snapshot
      ) {
        if (
          !Number.isInteger(message.frame) ||
          message.snapshot.frame !== message.frame
        )
          throw Error("Native snapshot frame mismatch");
        outgoing = {
          ...message,
          craneLive: sceneOwner.evidenceAtNativePublication(
            message.frame,
            message.snapshot,
          ),
        };
      }
      port.postMessage(outgoing, transfer ?? []);
    },
  };
  startGeneratedSimulationWorker({
    config: CONFIG,
    systems: [{ default: CraneCourtyard }],
    port: observedPort,
  });
});

sourceFiles.main.mjs:
import { startGeneratedBrowserApp } from "/worker-modules/packages/app/dist/browser.js";
import {
  createGeneratedCommandMessage,
  createApertureDevtoolsRequest,
} from "/worker-modules/packages/app/dist/commands.js";
import {
  installLiveEditTracking,
  runLiveEditHarness,
} from "/harness/client.mjs";
import { STATES, LIGHT } from "/harness/contract.mjs";
import { CONFIG, CAMERAS, PALETTE } from "./scene.mjs";
import { installNativeObserver } from "../native-observer.mjs";
import { installMirrorObserver } from "./mirror-observer.mjs";
import { webGpuAppRenderReportToJsonValue } from "/worker-modules/packages/webgpu/dist/index.js";
import { jsonValue } from "./native-evidence.mjs";
import {
  inspectFrameCorrespondence,
  inspectConsumedSnapshot,
} from "./frame-proof.mjs";

const tracking = installLiveEditTracking();
const topologyDraws = installNativeObserver();
const mirror = installMirrorObserver();
const published = new Map(),
  completed = new Map(),
  errors = [],
  publicationTrace = [],
  receptionTrace = [],
  stepAcks = [];
let latestGate = null,
  nativeRenderer = null;
const clone = (value) => JSON.parse(JSON.stringify(value));
const canvas = document.querySelector("#scene");
let workerObject = null;
window.__CRANE_LIVE_AUTHOR_PROGRESS__ = { phase: "boot" };
window.addEventListener("error", (event) =>
  errors.push({ type: "window-error", message: event.message }),
);
window.addEventListener("unhandledrejection", (event) =>
  errors.push({
    type: "rejection",
    message: String(event.reason?.stack ?? event.reason),
  }),
);

async function until(read, label) {
  const deadline = performance.now() + 180000;
  while (performance.now() < deadline) {
    if (errors.length) throw Error(`${label}: ${JSON.stringify(errors)}`);
    const value = read();
    if (value) return value;
    await new Promise((resolve) => requestAnimationFrame(resolve));
  }
  const diagnostics = nativeRenderer?.getDiagnostics({ detail: "full" });
  const trace = {
    latestGate,
    publicationTrace: publicationTrace.slice(-8),
    receptionTrace: receptionTrace.slice(-8),
    stepAcks: stepAcks.slice(-3),
    publishedFrames: [...published.keys()],
    completedFrames: [...completed.keys()],
    transport: diagnostics?.transport,
    cadence: diagnostics?.cadence,
    lastFrame: diagnostics?.lastFrame
      ? {
          frame: diagnostics.lastFrame.frame,
          ok: diagnostics.lastFrame.ok,
          counts: diagnostics.lastFrame.counts,
          renderTargets: diagnostics.lastFrame.renderTargets,
          diagnostics: diagnostics.lastFrame.diagnostics,
        }
      : null,
  };
  throw Error(
    `Timed out waiting for ${label}; retained correspondence diagnostics: ${JSON.stringify(trace)}`,
  );
}

try {
  const app = await startGeneratedBrowserApp({
    config: CONFIG,
    workerEntry: new URL("./worker.mjs", import.meta.url),
    workerStartOptions: {
      sharedSnapshotMessageRateHz: 240,
      sourceAssetsMessageRateHz: 240,
      workerFullSummaryIntervalMilliseconds: 16,
    },
    workerFactory: (url, options) => {
      if (workerObject) throw Error("Second Worker rejected");
      workerObject = new Worker(url, options);
      workerObject.addEventListener("message", (event) => {
        if (event.data?.type === "crane-live-publication-trace")
          publicationTrace.push(event.data);
      });
      return workerObject;
    },
  });
  if (!app.webgpu.ok)
    throw Error(`Native WebGPU failed: ${JSON.stringify(app.webgpu)}`);
  const renderer = app.webgpu.app;
  nativeRenderer = renderer;
  // Preserve the actual renderer and native method, observing its completion.
  const nativeRenderSnapshot = renderer.renderSnapshot;
  renderer.renderSnapshot = async function (snapshot, options) {
    const actualSnapshot = jsonValue(snapshot);
    const mirroredAssets = mirror.capture(snapshot);
    const drawScope = topologyDraws.begin(actualSnapshot.frame);
    let result, submittedDraws;
    try {
      result = await nativeRenderSnapshot.call(this, snapshot, options);
    } finally {
      submittedDraws = topologyDraws.end(drawScope);
    }
    if (
      result.frame !== actualSnapshot.frame ||
      result.snapshot.frame !== actualSnapshot.frame
    )
      throw Error(
        "Native renderSnapshot completion changed the input snapshot frame",
      );
    completed.set(result.frame, {
      frame: webGpuAppRenderReportToJsonValue(result),
      snapshot: actualSnapshot,
      submittedDraws,
      mirroredAssets,
    });
    return result;
  };
  app.worker.onError((event) => errors.push({ type: "worker", ...event }));
  app.worker.onSnapshot((event) => {
    const evidence = event.message.craneLive;
    receptionTrace.push({
      frame: event.frame,
      snapshotFrame: event.snapshot.frame,
      revision: evidence?.revision ?? null,
      stateId: evidence?.stateId ?? null,
      full: event.message.workerSummary?.summaryCadence?.full ?? null,
      postMessageReasons:
        event.message.workerSummary?.postMessageDecision?.postMessageReasons ??
        null,
    });
    if (!evidence) return;
    if (
      evidence.snapshotFrame !== event.frame ||
      evidence.snapshotFrameField !== event.snapshot.frame
    )
      throw Error(
        "Observed native worker snapshot frame disagrees with revision evidence",
      );
    published.set(event.frame, evidence);
  });
  app.worker.onMessage((message) => {
    if (
      message.type === "aperture.devtools.response" &&
      message.requestId?.startsWith("crane-live-")
    ) {
      stepAcks.push(clone(message));
      if (!message.ok) errors.push({ type: "step-failed", message });
    }
  });
  const sourceFiles = {};
  for (const file of [
    "scene.mjs",
    "scene-system.mjs",
    "worker.mjs",
    "main.mjs",
    "native-evidence.mjs",
    "mirror-observer.mjs",
    "frame-proof.mjs",
    "index.html",
  ]) {
    const response = await fetch(new URL(file, import.meta.url));
    if (!response.ok) throw Error(`Own source could not be retained: ${file}`);
    sourceFiles[file] = await response.text();
  }
  const appearance = {
    config: CONFIG.render,
    palette: PALETTE,
    cameraClearColor: [0.115, 0.17, 0.209, 1],
    lights: [LIGHT],
  };
  const adapter = {
    engine: "aperture",
    canvas,
    getRuntimeHandles() {
      return { renderer, scene: app.worker, worker: workerObject };
    },
    async applyAndSubmit(state) {
      const revision = state.index + 1;
      window.__CRANE_LIVE_AUTHOR_PROGRESS__ = {
        phase: "requesting-worker-edit",
        stateId: state.id,
        revision,
      };
      app.worker.postMessage(
        createGeneratedCommandMessage({
          channel: "crane.live.apply",
          payload: { id: state.id, index: state.index, revision },
        }),
      );
      app.worker.postMessage(
        createApertureDevtoolsRequest({
          requestId: `crane-live-${revision}`,
          tool: "ecs_step",
          payload: { delta: 1 / 60, time: revision / 60 },
        }),
      );
      const native = await until(() => {
        const diagnostics = renderer.getDiagnostics({ detail: "full" });
        if (diagnostics.lastError)
          throw Error(
            `Native renderer error: ${JSON.stringify(diagnostics.lastError)}`,
          );
        // A completed native method call and exact worker publication are both
        // necessary. Queue counters, step acknowledgments and parameter values
        // alone can never satisfy this gate.
        for (const submission of [...completed.values()].reverse()) {
          const gate = inspectFrameCorrespondence(state, published, submission);
          latestGate = gate;
          if (!gate.ok) continue;
          const evidence = published.get(submission.frame.frame);
          const consumedChecks = inspectConsumedSnapshot(
            evidence.nativeGeometry.meshes,
            submission.snapshot,
          );
          if (consumedChecks.some((check) => !check.ok))
            throw Error(
              `Actual renderer snapshot mismatch: ${JSON.stringify(consumedChecks.filter((check) => !check.ok))}`,
            );
          return {
            evidence,
            frame: clone(submission.frame),
            submittedSnapshot: submission.snapshot,
            submittedDraws: submission.submittedDraws,
            mirroredAssets: submission.mirroredAssets,
            consumedChecks,
          };
        }
        return null;
      }, `revision ${revision} on its actual native submitted snapshot frame`);
      this.last = native;
      return {
        stateId: state.id,
        revision,
        workerRevision: native.evidence.revision,
        submittedRevision: native.evidence.revision,
        nativeFrame: native.frame.frame,
        details: {
          correspondence:
            "Worker revision evidence attached to the exact native snapshot publication; native renderer report.frame equals that same snapshot.frame after successful swapchain submission.",
          workerSnapshotFrame: native.evidence.snapshotFrame,
          workerSnapshotFrameField: native.evidence.snapshotFrameField,
          nativeReportFrame: native.frame.frame,
          actualRenderSnapshotFrame: native.submittedSnapshot.frame,
          nativeRenderMethodCompletionObserved: true,
          nativeStepAcknowledgment:
            stepAcks.find(
              (ack) => ack.requestId === `crane-live-${revision}`,
            ) ?? null,
          nativeReportOk: native.frame.ok,
          nativeDrawCalls: native.frame.counts.drawCalls,
          submittedAssetVersions: native.evidence.resources.assetVersions,
          nativeFrameReport: native.frame,
        },
      };
    },
    async readEvidence(state, receipt) {
      const observed = this.last;
      if (
        observed.evidence.stateId !== state.id ||
        observed.evidence.revision !== receipt.revision ||
        observed.frame.frame !== receipt.nativeFrame
      )
        throw Error("Evidence/receipt drift");
      const native = clone(observed.evidence);
      native.nativeGeometry.mirroredAssets = observed.mirroredAssets;
      native.nativeGeometry.submittedDraws = observed.submittedDraws;
      native.nativeGeometry.actualSubmittedSnapshot =
        observed.submittedSnapshot;
      native.nativeChecks.checks.push(...observed.consumedChecks);
      native.nativeChecks.ok =
        native.nativeChecks.checks.every((check) => check.ok) &&
        errors.length === 0;
      native.sourceGeometry.sourceFiles = sourceFiles;
      return {
        ...native,
        camera: {
          position: CAMERAS["front-quarter"],
          target: [0, 1.4, 0],
          verticalSpan: 10.5,
          projection: "orthographic",
          aspect: 1,
          near: 0.1,
          far: 80,
        },
        appearance,
        resources: {
          worker: native.resources,
          gpu: observed.submittedDraws.counters,
          nativeRenderer: observed.frame.resourceReuse,
        },
        validationErrors: clone(errors),
        nativeCorrespondenceTrace: {
          publication: publicationTrace.slice(-3),
          reception: receptionTrace.slice(-3),
          gate: latestGate,
        },
        nativeSubmission: receipt.details,
        transport: nativeRenderer.getDiagnostics({ detail: "full" }).transport,
        limitations: [
          "GPU bytes are preserved native upload observations at each actual submission, not GPU readback. Cached shadow draws retain their original submission identity.",
          "This is a native dynamic-asset publication benchmark; replacement assets and typed arrays are explicitly counted, even when actual GPU buffers are reused.",
          "No engine changes, appearance retuning, new dependencies or geometry re-authoring.",
        ],
      };
    },
  };
  window.__CRANE_LIVE_ADAPTER__ = adapter;
  await runLiveEditHarness(adapter, { tracking });
  window.__CRANE_LIVE_AUTHOR_PROGRESS__ = {
    phase: "complete",
    states: STATES.length,
  };
} catch (error) {
  window.__CRANE_LIVE_AUTHOR_PROGRESS__ = {
    phase: "error",
    message: String(error.stack ?? error),
  };
  console.error(error);
  throw error;
}

