  const attribute = stream.attributes.find((a) => a.semantic === "POSITION");
  if (attribute.format !== "float32x3")
    throw Error(`Unsupported native POSITION format: ${attribute.format}`);
  const rawBytes = nativeEvidenceBytes(stream);
  const bytes = new DataView(
      rawBytes.buffer,
      rawBytes.byteOffset,
      rawBytes.byteLength,
