  for (const part of scene.parts) {
    const native = meshes.find((m) => m.name === part.name);
    if (!native) {
      checks.push({ name: `${part.name}:present`, ok: false });
      continue;
    }
    const expected = part.extrusion
      ? part.positions.flat()
      : part.indices.flatMap((i) => part.positions[i]);
    checks.push({
      name: `${part.name}:exact-native-positions`,
      ok: JSON.stringify(native.positions) === JSON.stringify(expected),
      vertices: native.positions.length / 3,
    });
    checks.push({
      name: `${part.name}:actual-indices`,
      ok:
        JSON.stringify(native.indices) ===
        JSON.stringify(part.extrusion ? part.indices : []),
    });
    checks.push({
      name: `${part.name}:ECS-world-matrix`,
      ok:
        JSON.stringify(native.worldMatrix) === JSON.stringify(part.worldMatrix),
    });
    const triangleIndices = native.indexed
      ? native.indices
      : Array.from({ length: native.positions.length / 3 }, (_, i) => i);
    const valid =
      triangleIndices.length % 3 === 0 &&
      triangleIndices.every(
        (i) =>
          Number.isInteger(i) && i >= 0 && i * 3 + 2 < native.positions.length,
      ) &&
      native.positions.every(Number.isFinite);
    checks.push({
      name: `${part.name}:finite-native-triangles`,
      ok: valid,
      triangles: triangleIndices.length / 3,
    });
  }
  return { ok: checks.every((c) => c.ok), checks };
}

