  return textureSample(inputTexture, inputSampler, clamp(uv, vec2f(0.0), vec2f(1.0))).rgb;
}

@fragment
fn fs(input: VertexOutput) -> @location(0) vec4f {
  let texel = blurParams.invSize;
  let uv = input.uv;
  var color = sampleColor(uv) * GAUSSIAN_COEFFICIENTS[0];
