@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var baseTexture: texture_2d<f32>;
@group(0) @binding(2) var bloomTexture0: texture_2d<f32>;
@group(0) @binding(3) var bloomTexture1: texture_2d<f32>;
@group(0) @binding(4) var bloomTexture2: texture_2d<f32>;
@group(0) @binding(5) var bloomTexture3: texture_2d<f32>;
@group(0) @binding(6) var bloomTexture4: texture_2d<f32>;

const BLOOM_INTENSITY = 0.025000;
const BLOOM_RADIUS = 0.125000;

fn sampleBase(uv: vec2f) -> vec4f {
  return textureSample(baseTexture, inputSampler, clamp(uv, vec2f(0.0), vec2f(1.0)));
}

fn lerpBloomFactor(factor: f32) -> f32 {
  let mirrorFactor = 1.2 - factor;
  return mix(factor, mirrorFactor, BLOOM_RADIUS);
}


fn sampleBloom0(uv: vec2f) -> vec3f {
  return textureSample(bloomTexture0, inputSampler, clamp(uv, vec2f(0.0), vec2f(1.0))).rgb;
}

fn sampleBloom1(uv: vec2f) -> vec3f {
  return textureSample(bloomTexture1, inputSampler, clamp(uv, vec2f(0.0), vec2f(1.0))).rgb;
}

fn sampleBloom2(uv: vec2f) -> vec3f {
  return textureSample(bloomTexture2, inputSampler, clamp(uv, vec2f(0.0), vec2f(1.0))).rgb;
}

fn sampleBloom3(uv: vec2f) -> vec3f {
  return textureSample(bloomTexture3, inputSampler, clamp(uv, vec2f(0.0), vec2f(1.0))).rgb;
}

fn sampleBloom4(uv: vec2f) -> vec3f {
  return textureSample(bloomTexture4, inputSampler, clamp(uv, vec2f(0.0), vec2f(1.0))).rgb;
}

@fragment
fn fs(input: VertexOutput) -> @location(0) vec4f {
  let uv = input.uv;
  let base = sampleBase(uv);
  var bloom = vec3f(0.0);
  bloom += sampleBloom0(uv) * lerpBloomFactor(1.000000);
  bloom += sampleBloom1(uv) * lerpBloomFactor(0.800000);
  bloom += sampleBloom2(uv) * lerpBloomFactor(0.600000);
  bloom += sampleBloom3(uv) * lerpBloomFactor(0.400000);
  bloom += sampleBloom4(uv) * lerpBloomFactor(0.200000);
  let color = base.rgb + bloom * BLOOM_INTENSITY;
  return vec4f(color, base.a);
}

fn apertureOutputTonemap(inputColor: vec3f, exposure: f32) -> vec3f {
  let color = inputColor * exposure;
  let agxInset = mat3x3<f32>(
    vec3f(0.856627153315983, 0.137318972929847, 0.11189821299995),
    vec3f(0.0951212405381588, 0.761241990602591, 0.0767994186031903),
    vec3f(0.0482516061458583, 0.101439036467562, 0.811302368396859)
  );
  let agxOutset = mat3x3<f32>(
    vec3f(1.1271005818144368, -0.1413297634984383, -0.14132976349843826),
    vec3f(-0.11060664309660323, 1.157823702216272, -0.11060664309660294),
    vec3f(-0.016493938717834573, -0.016493938717834257, 1.2519364065950405)
  );
  let linSrgbToRec2020 = mat3x3<f32>(
    vec3f(0.6274, 0.0691, 0.0164),
    vec3f(0.3293, 0.9195, 0.0880),
    vec3f(0.0433, 0.0113, 0.8956)
  );
  let linRec2020ToSrgb = mat3x3<f32>(
    vec3f(1.6605, -0.1246, -0.0182),
    vec3f(-0.5876, 1.1329, -0.1006),
    vec3f(-0.0728, -0.0083, 1.1187)
  );
  let minEv = -12.47393;
  let maxEv = 4.026069;

  var c = linSrgbToRec2020 * color;
  c = agxInset * c;
  c = max(c, vec3f(1e-10));
  c = log2(c);
  c = (c - vec3f(minEv)) / (maxEv - minEv);
  c = clamp(c, vec3f(0.0), vec3f(1.0));

  let x2 = c * c;
  let x4 = x2 * x2;
  c = 15.5 * x4 * x2 - 40.14 * x4 * c + 31.96 * x4 -
    6.868 * x2 * c + 0.4298 * x2 + 0.1191 * c - vec3f(0.00232);

  c = agxOutset * c;
  c = pow(max(vec3f(0.0), c), vec3f(2.2));
  c = linRec2020ToSrgb * c;
  return clamp(c, vec3f(0.0), vec3f(1.0));
}

fn apertureLinearToSrgbChannel(value: f32) -> f32 {
  let clamped = clamp(value, 0.0, 1.0);

  if (clamped <= 0.0031308) {
    return 12.92 * clamped;
  }

  return 1.055 * pow(clamped, 1.0 / 2.4) - 0.055;
}

fn apertureOutputColorSpace(color: vec3f) -> vec3f {
  return vec3f(
    apertureLinearToSrgbChannel(color.r),
    apertureLinearToSrgbChannel(color.g),
    apertureLinearToSrgbChannel(color.b),
  );
}

struct VertexOutput {
  @builtin(position) position: vec4f,
  @location(0) uv: vec2f,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;

const APERTURE_EXPOSURE: f32 = 1.0;

@vertex
fn vs(@builtin(vertex_index) vertexIndex: u32) -> VertexOutput {
  var positions = array<vec2f, 3>(
    vec2f(-1.0, 3.0),
    vec2f(-1.0, -1.0),
    vec2f(3.0, -1.0),
  );
  // Flip V vs clip-space Y: WebGPU framebuffer row 0 (texture v=0) is the TOP of
  // the rendered scene, while clip-space y=+1 is the top of the screen. Mapping
  // uv = (pos+1)/2 would sample scene-bottom at screen-top (vertical flip); the
  // (1 - clipY)/2 mapping keeps the blit upright.
  var uvs = array<vec2f, 3>(
    vec2f(0.0, -1.0),
    vec2f(0.0, 1.0),
    vec2f(2.0, 1.0),
  );
  var output: VertexOutput;
  output.position = vec4f(positions[vertexIndex], 0.0, 1.0);
  output.uv = uvs[vertexIndex];
  return output;
}

@fragment
fn fs(input: VertexOutput) -> @location(0) vec4f {
  let hdr = textureSample(inputTexture, inputSampler, clamp(input.uv, vec2f(0.0), vec2f(1.0)));
  let tonemapped = apertureOutputTonemap(hdr.rgb, APERTURE_EXPOSURE);
  let encoded = apertureOutputColorSpace(tonemapped);
  return vec4f(encoded, hdr.a);
}
